/// @brief 仅封装一只演员的显式世界参数；HP/分数使用原始点数，随机 X 只在出生时按固定 seed 求值。
/// 同一队列统一高度；种子已逐实例固定，不由生产表的行号推导；素材由本关清单借用。
SpawnActors Spawn(Vector3 position,const behavior::Pattern& pattern,float health,int score,int item,
                  bool mirrored,bool randomX,unsigned seed,VisualId visual,float radius) {
    return {behavior::Spawn{.position=position,.pattern=pattern,.mirrored=mirrored,.randomX=randomX,
        .sourceHealth=health,.sourceScore=score,.seed=seed,.sourceItem=item,.visual=visual,.hitRadius=radius,
        .bulletBase=kNativeBulletBase,.laserBase=kNativeLaserBase,.defeatBase=kNativeDefeat,.fallback=kBlueBullet,
        .retirementHeights=Vector2{-10.5F,10.5F}},1,0};
}
